class Fibonacci {
    public function generate($n) {
        $sequence = [];
        $a = 0;
        $b = 1;

        while ($b <= $n) {
            $sequence[] = $a;
            $temp = $b;
            $b = $a + $b;
            $a = $temp;
        }

        return $sequence;
    }
}
